package main

import "fmt"

// Any type with Error() string satisfies error.
type rateLimitError struct{ retryAfter int }

func (e rateLimitError) Error() string {
	return fmt.Sprintf("rate limited, retry after %ds", e.retryAfter)
}

func main() {
	var err error = rateLimitError{retryAfter: 5}
	if err != nil {
		fmt.Println(err)
	}
	// Output: rate limited, retry after 5s
}

package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found") // owned by this package

func lookup(id int) error {
	return fmt.Errorf("user %d: %w", id, ErrNotFound)
}

func main() {
	err := lookup(7)
	fmt.Println(errors.Is(err, ErrNotFound))
