}

package main

import (
	"errors"
	"fmt"
)

var ErrTimeout = errors.New("timeout")

func main() {
	base := ErrTimeout
	wrapped := fmt.Errorf("query users: %w", base) // %w preserves the chain
	flat := fmt.Errorf("query users: %v", base)    // %v drops it
	fmt.Println(errors.Is(wrapped, ErrTimeout))
	fmt.Println(errors.Is(flat, ErrTimeout))
	// Output: true
	// false
}

