type QueryError struct {
	Op  string
	Err error // the wrapped cause
}

func (e *QueryError) Error() string { return e.Op + ": " + e.Err.Error() }
func (e *QueryError) Unwrap() error { return e.Err } // join the chain

func main() {
	base := errors.New("connection reset")
	err := &QueryError{Op: "selectUser", Err: base}
	fmt.Println(errors.Is(err, base)) // Unwrap lets Is see through
	// Output: true
}

package main

import (
	"errors"
	"net/http"
)

var ErrNotFound = errors.New("not found")

func statusFor(err error) (int, string) {
	switch {
	case errors.Is(err, ErrNotFound):
		return http.StatusNotFound, "not found" // safe client message
	default:
		return http.StatusInternalServerError, "internal error"
	}
}

func handle(w http.ResponseWriter, err error) {
	code, msg := statusFor(err)
	http.Error(w, msg, code) // log the full chain once elsewhere
}

package main

import (
	"errors"
	"fmt"
)

var ErrEmpty = errors.New("empty")
var ErrTooLong = errors.New("too long")

func validate(name string) error {
	var errs error
	if name == "" {
		errs = errors.Join(errs, ErrEmpty)
	}
	if len(name) > 100 {
		errs = errors.Join(errs, ErrTooLong)
	}
	return errs
}

func main() {
	err := validate("")
	fmt.Println(errors.Is(err, ErrEmpty))
	// Output: true
}

