package solution

import "errors"

// ErrNotFound is the package's not-found sentinel.
var ErrNotFound = errors.New("not found")

// ValidationError carries which field failed validation.
type ValidationError struct {
	Field string
}

func (e *ValidationError) Error() string {
	return "invalid field: " + e.Field
}

// Classify inspects the (possibly wrapped) error and labels it.
func Classify(err error) string {
	if err == nil {
		return "none"
	}
	if errors.Is(err, ErrNotFound) { // sentinel: identity match anywhere in chain
		return "not_found"
	}
	var ve *ValidationError
	if errors.As(err, &ve) { // typed: extract from anywhere in chain
		return "validation"
	}
	return "unknown"
}

