package solution

import "errors"

// retryableError marks its wrapped error as safe to retry.
type retryableError struct{ err error }

func (e *retryableError) Error() string { return e.err.Error() }
func (e *retryableError) Unwrap() error { return e.err } // participate in the chain

// Retryable tags an error as retryable. nil stays nil.
func Retryable(err error) error {
	if err == nil {
		return nil
	}
	return &retryableError{err: err}
}

// IsRetryable reports whether any error in the chain is retryable.
func IsRetryable(err error) bool {
	var re *retryableError
	return errors.As(err, &re) // walks the chain for the marker type
}

package apierr

import (
	"errors"
	"net/http"
)

// Kind is a transport-agnostic error classification.
type Kind int

const (
	KindInternal Kind = iota
	KindNotFound
	KindInvalid    // validation / bad request
	KindConflict
	KindUnavailable // transient / retryable
)

// DomainError carries a Kind and a safe message, wrapping the underlying cause.
type DomainError struct {
	Kind Kind
	Msg  string
	err  error // wrapped cause; kept off the wire
}

func (e *DomainError) Error() string {
	if e.err != nil {
		return e.Msg + ": " + e.err.Error()
	}
	return e.Msg
}

// Unwrap lets errors.Is/As walk to the underlying cause.
func (e *DomainError) Unwrap() error { return e.err }

// Wrap tags a cause with a Kind and safe message. nil stays nil.
func Wrap(kind Kind, msg string, cause error) error {
	if cause == nil {
		return nil
	}
	return &DomainError{Kind: kind, Msg: msg, err: cause}
}

// HTTPStatus maps any wrapped DomainError to a status code, default 500.
func HTTPStatus(err error) int {
	var de *DomainError
	if !errors.As(err, &de) { // find the DomainError anywhere in the chain
		return http.StatusInternalServerError
	}
	switch de.Kind {
	case KindNotFound:
		return http.StatusNotFound
	case KindInvalid:
		return http.StatusBadRequest
	case KindConflict:
		return http.StatusConflict
	case KindUnavailable:
		return http.StatusServiceUnavailable
	default: // KindInternal or unknown
		return http.StatusInternalServerError
	}
}
